def solve_parenthesis_sequence(n, s):
    # Initialize variables
    open_count = 0
    close_needed = 0
    result = []

    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            if open_count > 0:
                open_count -= 1
            else:
                close_needed += 1
        else:  # char == '?'
            if open_count > 0:
                open_count -= 1
                result.append('(')
            else:
                close_needed += 1
                result.append(')')

    # Check if we have enough '?' to balance the sequence
    if open_count != close_needed:
        return ":("

    # Balance the remaining '?' to form a valid sequence
    for _ in range(open_count):
        result.append(')')

    return ''.join(result)

